/* INTERFACE */
@font-face {
    font-family: "Alegreya Sans";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Alegreya Sans";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-weight: normal;
    font-style: italic;
    font-display: swap;
}

@font-face {
    font-family: "Alegreya Sans";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-weight: bold;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Alegreya Sans";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-weight: bold;
    font-style: italic;
    font-display: swap;
}

/* TEXT */
@font-face {
    font-family: "Alegreya Var";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Alegreya Var";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-style: italic;
    font-display: swap;
}

@font-face {
    font-family: "Times New Roman";
    src: url("data:font/woff2;charset=utf-8;base64,")
        format("woff2");
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Times New Roman";
    src: url("data:font/woff2;charset=utf-8;base64,")
        format("woff2");
    font-weight: normal;
    font-style: italic;
    font-display: swap;
}

@font-face {
    font-family: "Times New Roman";
    src: url("data:font/woff2;charset=utf-8;base64,")
        format("woff2");
    font-weight: bold;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Times New Roman";
    src: url("data:font/woff2;charset=utf-8;base64,")
        format("woff2");
    font-weight: bold;
    font-style: italic;
    font-display: swap;
}

/* MONOSPACE */
@font-face {
    font-family: "Monaspace Xenon Var";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-display: swap;
    font-feature-settings:
        "liga",
        "calt",
        "ss01",
        "ss02",
        "ss03",
        "ss04",
        "ss05",
        "ss06",
        "ss07",
        "ss08",
        "ss09",
        "ss10",
        "cv01" 0,
        "cv02" 0,
        "cv10" 1,
        "cv31" 1;
}

/* EMOJI */
@font-face {
    font-family: "DoCoMo Emoji";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-display: swap;
}

@font-face {
    font-family: "Noto Emoji Var";
    src: url("data:font/ttf;base64,")
        format("truetype");
    font-display: swap;
}

body {
    --font-sans-serif: "Alegreya Sans", "DoCoMo Emoji", sans-serif;
    --font-serif:
        "Alegreya Var", "Times New Roman", Times, "DoCoMo Emoji", serif;
    --font-monospace: "Monaspace Xenon Var", "DoCoMo Emoji", monospace;

    --font-interface: var(--font-sans-serif);
    --font-text: var(--font-serif);

    --font-interface-theme: var(--font-interface);
    --font-text-theme: var(--font-text);
    --font-monospace-theme: var(--font-monospace);

    font-feature-settings: "onum";
    font-variant-ligatures: common-ligatures discretionary-ligatures contextual;
}
